	if err != nil {
		fmt.Fprintln(os.Stderr, "Invalid input: please provide a valid integer")
		os.Exit(1)
	}

	for i := 2; i <= n; i++ {
		if isPrime(i) {
			fmt.Println(i)
		}
	}
}
