{
    double tolerance = 1e-9;
    if (Math.Abs(expected - actual) < tolerance)
    {
        Console.WriteLine($"PASS: {description}");
    }
    else
    {
        Console.WriteLine($"FAIL: {description} (expected: {expected}, got: {actual})");
    }
}

